select jsonb_build_object('relations',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'options',c.reloptions) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','authorization_private','booking_private','customer_private','enquiry_private','invoice_private','quote_private','request_private','staff_private','waitlist_private') and c.relkind in ('r','v','S')), 'columns',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'acl',a.attacl) order by n.nspname,c.relname,a.attnum) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where n.nspname in ('public','authorization_private','booking_private','customer_private','enquiry_private','invoice_private','quote_private','request_private','staff_private','waitlist_private') and c.relkind in ('r','v') and a.attnum>0 and not a.attisdropped),'policies',(select jsonb_agg(to_jsonb(p) order by schemaname,tablename,policyname) from pg_policies p where schemaname in ('public','authorization_private','booking_private','customer_private','enquiry_private','invoice_private','quote_private','request_private','staff_private','waitlist_private')),'constraints',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',x.conname,'definition',pg_get_constraintdef(x.oid)) order by n.nspname,c.relname,x.conname) from pg_constraint x join pg_class c on c.oid=x.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','authorization_private','booking_private','customer_private','enquiry_private','invoice_private','quote_private','request_private','staff_private','waitlist_private')),'triggers',(select jsonb_agg(pg_get_triggerdef(t.oid) order by t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','authorization_private','booking_private','customer_private','enquiry_private','invoice_private','quote_private','request_private','staff_private','waitlist_private') and not t.tgisinternal),'views',(select jsonb_agg(jsonb_build_object('schema',schemaname,'name',viewname,'definition',definition) order by schemaname,viewname) from pg_views where schemaname in ('public','authorization_private','booking_private','customer_private','enquiry_private','invoice_private','quote_private','request_private','staff_private','waitlist_private'))) as inventory;
